-- 23-fk-treatment-association.sql
-- V5-SPACETENANCYKEY-001, multi-space step 2.1 (plan V204 §2.1, §3 row 2.1). File 23 of 25.
-- public.treatment_association already carries workspace_id (NOT NULL, DEFAULT the one Space); it gains the key only.
-- Stamp 5.3.13-tenancykey-001-fk-treatment-association.
-- GENERATED by generate.mjs from owner-classes.json. Edit those, run `node generate.mjs --write`;
--   tenancykey.test.js reds on any difference.
--
-- WHAT, in one transaction:
--   0. LOCK treatment_association (SHARE ROW EXCLUSIVE: writers wait, readers do not), so the guard and the key see the
--      same rows.
--   1. The guard ($pregate$): the env, the database's fingerprint, the column as expected (uuid NOT NULL), and
--      every row naming a Space. A row that names no Space refuses: under a NOT VALID key a second UPDATE of
--      such a row in one transaction raises 23503 (v5-spacefk-001 README, "Why fold first").
--   2. FOREIGN KEY (workspace_id) -> public.spaces(id) ON DELETE RESTRICT NOT VALID, single column (C-BLOCK).
--      No row scan. Step 2.3 validates it.
--   3. Comment and the stamp.
-- ENV. As every file here: psql -v env=prod|staging; missing, other, or the other database's fingerprint
--   refuses.
-- DEPLOYED CODE. Every deployed writer either takes the column DEFAULT or writes the literal one Space
--   (README.md "Arming census"): a Space on both envs, so no INSERT meets the key.
-- LOCKS. SHARE ROW EXCLUSIVE on treatment_association and on spaces, to COMMIT. lock_timeout 5s.
-- RE-RUN. With the stamp present nothing changes. A key of this name without the stamp refuses.
-- ROLLBACK: 0r-rollback.sql.

BEGIN;

SET LOCAL lock_timeout = '5s';
SELECT set_config('tenancykey.env', :'env', true) AS env \gset tk_

LOCK TABLE public.treatment_association IN SHARE ROW EXCLUSIVE MODE;

-- ── 1. The guard (read-only: the runner's --dry-run runs this block alone). ───────────────────────────────
DO $pregate$
DECLARE
  v_env text := current_setting('tenancykey.env', true);
  v_bad text;
  v_def text;
BEGIN
  IF v_env IS NULL OR v_env NOT IN ('prod', 'staging') THEN
    RAISE EXCEPTION 'v5-tenancykey-001 23 (treatment_association) refused, nothing changed: env is %, not prod or staging.', coalesce(quote_literal(v_env), 'unset')
      USING HINT = 'Run it with psql -v env=prod or -v env=staging (scripts/tenancykey-apply.py does).';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.schema_version
                  WHERE version = CASE v_env WHEN 'prod' THEN '4.0.0-pot-001' ELSE '4.23.9-cascadesweep-001-rollback' END)
     OR EXISTS (SELECT 1 FROM public.schema_version
                 WHERE version = CASE v_env WHEN 'prod' THEN '4.23.9-cascadesweep-001-rollback' ELSE '4.0.0-pot-001' END) THEN
    RAISE EXCEPTION 'v5-tenancykey-001 23 (treatment_association) refused, nothing changed: this database does not carry the % fingerprint (owner-classes.json "fingerprint").', v_env
      USING HINT = 'The -v env value names the other database. Check which URL this is before anything else.';
  END IF;
  IF EXISTS (SELECT 1 FROM public.schema_version WHERE version = '5.3.13-tenancykey-001-fk-treatment-association') THEN
    RAISE NOTICE 'v5-tenancykey-001 23 (treatment_association): stamp 5.3.13-tenancykey-001-fk-treatment-association present; nothing to check.';
    RETURN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_attribute a
                   JOIN pg_class c ON c.oid = a.attrelid
                   JOIN pg_namespace n ON n.oid = c.relnamespace
                  WHERE n.nspname = 'public' AND c.relname = 'treatment_association'
                    AND a.attname = 'workspace_id' AND NOT a.attisdropped
                    AND a.atttypid = 'uuid'::regtype AND a.attnotnull) THEN
    RAISE EXCEPTION 'v5-tenancykey-001 23 (treatment_association) refused, nothing changed: public.treatment_association.workspace_id is not a NOT NULL uuid column.';
  END IF;
  SELECT string_agg(format('%s: %s row(s)', x.workspace_id, x.n), ', ' ORDER BY x.workspace_id::text)
    INTO v_bad
    FROM (SELECT t.workspace_id, count(*) AS n
            FROM public.treatment_association t
           WHERE NOT EXISTS (SELECT 1 FROM public.spaces s WHERE s.id = t.workspace_id)
           GROUP BY t.workspace_id) x;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'v5-tenancykey-001 23 (treatment_association) refused, nothing changed: row(s) name no Space: %', v_bad;
  END IF;
END $pregate$;

-- ── 2. The key, once. ───────────────────────────────────────────────────────────────────────────────────
DO $ddl$
BEGIN
  IF EXISTS (SELECT 1 FROM public.schema_version WHERE version = '5.3.13-tenancykey-001-fk-treatment-association') THEN
    RAISE NOTICE 'v5-tenancykey-001 23 (treatment_association): already applied; nothing changed.';
    RETURN;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_constraint k
               JOIN pg_class c ON c.oid = k.conrelid
               JOIN pg_namespace n ON n.oid = c.relnamespace
              WHERE n.nspname = 'public' AND c.relname = 'treatment_association' AND k.conname = 'treatment_association_workspace_id_fkey') THEN
    RAISE EXCEPTION 'v5-tenancykey-001 23 (treatment_association) refused, nothing changed: treatment_association_workspace_id_fkey exists but stamp 5.3.13-tenancykey-001-fk-treatment-association does not.'
      USING HINT = 'Something other than this file added it. Find what, before anything else.';
  END IF;

  ALTER TABLE public.treatment_association
    ADD CONSTRAINT treatment_association_workspace_id_fkey
    FOREIGN KEY (workspace_id) REFERENCES public.spaces (id) ON DELETE RESTRICT NOT VALID;
END $ddl$;

-- ── 3. Comment and the stamp. ────────────────────────────────────────────────────────────────────────────
COMMENT ON CONSTRAINT treatment_association_workspace_id_fkey ON public.treatment_association IS
  'V5-SPACETENANCYKEY-001 (v5-tenancykey-001 23, step 2.1). A row''s Space is a row of public.spaces. RESTRICT: a Space with rows here cannot be deleted. NOT VALID until step 2.3.';

INSERT INTO public.schema_version (version, description)
VALUES ('5.3.13-tenancykey-001-fk-treatment-association',
        'TENANCYKEY fk treatment_association: V5-SPACETENANCYKEY-001 (multi-space step 2.1, file 23 of 25). '
        'treatment_association_workspace_id_fkey -> spaces(id) ON DELETE RESTRICT NOT VALID on the existing workspace_id. Section '
        || current_setting('tenancykey.env') || '.')
